-- Ejecuta en Supabase > SQL Editor. No modifica la tabla ESTUDIANTE.
create table if not exists public."USUARIOS_ADMIN" (
  "ID_ADMIN" bigint generated by default as identity primary key,
  "NOMBRE_COMPLETO" text not null,
  "USUARIO" text,
  "CORREO" text not null unique,
  "CONTRASEÑA" text not null,
  "ACTIVO" boolean not null default true,
  "FECHA_CREACION" timestamptz not null default now()
);

-- Migración segura si USUARIOS_ADMIN ya existía sin la columna USUARIO.
alter table public."USUARIOS_ADMIN" add column if not exists "USUARIO" text;
update public."USUARIOS_ADMIN" set "USUARIO" = 'admin_' || "ID_ADMIN"::text where "USUARIO" is null or btrim("USUARIO") = '';
alter table public."USUARIOS_ADMIN" alter column "USUARIO" set not null;

create unique index if not exists usuarios_admin_usuario_lower_idx on public."USUARIOS_ADMIN" (lower("USUARIO"));
create unique index if not exists usuarios_admin_correo_lower_idx on public."USUARIOS_ADMIN" (lower("CORREO"));
